/**
 * @value 需要转换为string的json值
 */
export function jsonStringify(value) {
    try {
        return JSON.stringify(value);
    }
    catch (e) {
        return value;
    }
}
/**
 * @value 需要转换为实体对象的json值
 */
export function jsonParse(value) {
    try {
        if (typeof value === "string") {
            return JSON.parse(value);
        }
        return value;
    }
    catch (e) {
        return value;
    }
}
